363	/// `declarations` entries read `"<node index>.<kind>.<path>"`: the path is lower-cased, as the checker keys files.
364	pub(crate) fn declared_in(declaration: &str) -> &str {
365	    declaration.splitn(3, '.').nth(2).unwrap_or("")
366	}
367	
368	/// Whether `converted` holds more than `budget` types, itself and every type inside it counted. Counted on the tree,
369	/// not by serializing it, and only as far as the budget: the walk stops at the first type past it.
370	fn past_size_budget(converted: &PropType, budget: usize) -> bool {
371	    let mut count = 0usize;
372	    let mut pending = vec![converted];
373	    while let Some(ty) = pending.pop() {
374	        count += 1;
375	        if count > budget {
376	            return true;
377	        }
378	        match ty {
379	            PropType::String
380	            | PropType::Number
381	            | PropType::Boolean
382	            | PropType::Null
383	            | PropType::Undefined
384	            | PropType::Any
385	            | PropType::Never
386	            | PropType::Unknown
387	            | PropType::Void
388	            | PropType::BigInt
389	            | PropType::StringLiteral(_)
390	            | PropType::NumberLiteral(_)
391	            | PropType::BoolLiteral(_)
392	            | PropType::BigIntLiteral(_)
393	            | PropType::UniqueSymbol { .. }
394	            | PropType::EnumMember { .. }
395	            | PropType::Truncated { .. }
396	            | PropType::ReactNode
397	            | PropType::CssProperties
398	            | PropType::Ref { .. }
399	            | PropType::ElementType
400	            | PropType::HtmlAttributes { .. }
401	            | PropType::LiteralUnion { .. }
402	            | PropType::SxProps
403	            | PropType::Opaque(_) => {}
404	            PropType::TemplateLiteral(parts) => pending.extend(parts.iter().filter_map(|part| match part {
405	                TemplatePart::Text(_) => None,
406	                TemplatePart::Type(ty) => Some(ty),
407	            })),
408	            PropType::Union(members)
409	            | PropType::Intersection(members)
410	            | PropType::Named { args: members, .. }
411	            | PropType::Recursive { args: members, .. } => pending.extend(members),
412	            PropType::Array(inner) | PropType::Readonly(inner) => pending.push(inner),
413	            PropType::Tuple(elements) => pending.extend(elements.iter().map(|element| &element.element_type)),
414	            PropType::Object(fields) => push_fields(fields, &mut pending),
415	            PropType::Callable { signatures, fields } => {
416	                for signature in signatures {
417	                    pending.extend(signature.params.iter().map(|param| &param.param_type));
418	                    pending.push(&signature.return_type);
419	                }
420	                push_fields(fields, &mut pending);
421	            }
422	            PropType::Function { params, return_type, .. } => {
423	                pending.extend(params.iter().map(|param| &param.param_type));
424	                pending.push(return_type);
425	            }
426	        }
427	    }
428	    false
429	}
430	
431	/// The types of `fields` for [`past_size_budget`]: each field's, and an index signature's key type.
432	fn push_fields<'a>(fields: &'a [ObjectField], pending: &mut Vec<&'a PropType>) {
433	    for field in fields {
434	        pending.push(&field.prop_type);
435	        if let Some(key) = &field.index_key {
436	            pending.push(key);
437	        }
438	    }
439	}
440	
441	/// A converted type, with the enclosing instantiations its conversion depended on.
442	#[derive(Debug)]
443	struct Entry {
444	    /// Every handle the conversion compared against the instantiations enclosing it, sorted.
445	    asked: Arc<[u64]>,
446	    /// Those of `asked` that did enclose it.
447	    enclosed_by: Vec<u64>,
448	    converted: PropType,
449	}
450	
451	impl Entry {
452	    /// Whether the conversion would go the same way inside `enclosing`: among the handles it asked about, the ones
453	    /// that enclose the type there are exactly `enclosed_by`.
454	    fn holds_in(&self, enclosing: &[u64]) -> bool {
455	        self.enclosed_by.iter().all(|id| enclosing.contains(id))
456	            && enclosing.iter().all(|id| self.enclosed_by.contains(id) || self.asked.binary_search(id).is_err())
457	    }
458	}
459	
460	type Memo = Mutex<FxHashMap<(u64, u8), Vec<Arc<Entry>>>>;
461	
462	/// The parts of each type asked about so far, by (type handle, which parts), as the text the checker answered: read
463	/// again on each use, which costs a fraction of the round trip, and is several times smaller than the read lists.
464	type PartsSeen = Mutex<FxHashMap<(u64, Parts), Arc<RawValue>>>;
465	
466	/// The props answered so far, by the hash of their [`PropKey`] and then the key itself, owned.
467	type KeptProps = Mutex<FxHashMap<u64, Vec<(KeptKey, Arc<SemanticProp>)>>>;
468	
469	/// Everything a component's prop is made of ([`crate::component::props_of_type`]): its property's name, optionality and
470	/// declarations, the symbol it is a member of (its JSDoc's key when it has no declaration: the symbol itself), its type's
471	/// handle, and which of its JSDoc the component asks for. Two props of one snapshot with equal keys are the same prop: the
472	/// type is converted from the handle alone at the top ([`Converter::convert_roots`]), and where it is declared and its
473	/// JSDoc are read from the declarations, the parent and the symbol alone ([`crate::declared`]). Chakra's components
474	/// share a thousand style props, each a union converted from the same handle, so a component after the first finds
475	/// them here and neither converts, copies nor interns them again.
476	///
477	/// The key borrows what it is made of from the property: most props are found kept, and only one that is not is copied,
478	/// into the [`KeptKey`] it is kept by.
479	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
480	pub(crate) struct PropKey<'a> {
481	    hash: u64,
482	    name: &'a str,
483	    optional: bool,
484	    type_id: u64,
485	    declarations: &'a [String],
486	    parent: Option<&'a CompactSymbol>,
487	    /// The symbol's reference, only for a property with no declaration.
488	    symbol: Option<&'a str>,
489	    description: bool,
490	    tags: bool,
491	}
492	
493	impl<'a> PropKey<'a> {
494	    pub(crate) fn of(property: &'a SymbolInfo, prop_type: &TypeInfo, description: bool, tags: bool) -> Self {
495	        use std::hash::{Hash, Hasher};
496	        let optional = property.flags & flag::SYMBOL_OPTIONAL != 0;
497	        let symbol = property.declarations.is_empty().then(|| property.reference.text());
498	        let parent = property.parent.as_ref();
499	        let mut hasher = rustc_hash::FxHasher::default();
500	        (&property.name, optional, prop_type.id, &property.declarations, parent, symbol, description, tags)
501	            .hash(&mut hasher);
502	        PropKey {
503	            hash: hasher.finish(),
504	            name: &property.name,
505	            optional,
506	            type_id: prop_type.id,
507	            declarations: &property.declarations,
508	            parent,
509	            symbol,
510	            description,
511	            tags,
512	        }
513	    }
514	
515	    /// Whether `kept` was made from what this key names.
516	    fn names(&self, kept: &KeptKey) -> bool {
517	        self.name == kept.name
518	            && self.optional == kept.optional
519	            && self.type_id == kept.type_id
520	            && self.declarations == kept.declarations.as_slice()
521	            && self.parent == kept.parent.as_ref()
522	            && self.symbol == kept.symbol.as_deref()
523	            && self.description == kept.description
524	            && self.tags == kept.tags
525	    }
526	
527	    fn to_kept(self) -> KeptKey {
528	        KeptKey {
529	            name: self.name.to_string(),
530	            optional: self.optional,
531	            type_id: self.type_id,
532	            declarations: self.declarations.to_vec(),
533	            parent: self.parent.cloned(),
534	            symbol: self.symbol.map(str::to_string),
535	            description: self.description,
536	            tags: self.tags,
537	        }
538	    }
539	}
540	
541	/// A [`PropKey`] that owns what it is made of, for a prop kept for the components after its own.
542	#[derive(Debug)]
543	struct KeptKey {
544	    name: String,
545	    optional: bool,
546	    type_id: u64,
547	    declarations: Vec<String>,
548	    parent: Option<CompactSymbol>,
549	    symbol: Option<String>,
550	    description: bool,
551	    tags: bool,
552	}
553	
554	/// Which parts of a type [`Converter::parts`] asks for.
555	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
556	enum Parts {
557	    /// A union's, intersection's or template literal's members (`getTypesOfType`).
558	    Members,
559	    /// A reference's type arguments (`getTypeArguments`), the `this` type the checker appends included.
560	    Arguments,
561	}
562	
563	/// The type arguments a reference names, without the `this` type the checker appends to a class's or interface's.
564	fn without_this(arguments: &[TypeInfo]) -> &[TypeInfo] {
565	    let named = arguments.iter().rposition(|argument| !argument.is_this_type).map_or(0, |last| last + 1);
566	    arguments.get(..named).unwrap_or_default()
567	}
568	
569	#[derive(Default)]
570	struct State {
571	    /// Conversions by (type handle, depth), each entry with the enclosing instantiations it depended on. The handles
572	    /// are valid inside this snapshot only.
573	    ///
574	    /// Why an entry may be reused where [`Entry::holds_in`] says. A conversion reads its context in two ways only: the
575	    /// depth, which is in the key, and [`Cx::encloses`], the question whether a handle is an instantiation being
576	    /// expanded around the type. Everything else it reads is the checker's answer about the type, which does not change
577	    /// inside a snapshot. So a conversion is a deterministic walk whose every step is fixed by the type, the depth and
578	    /// the answers to those questions, in the order they are asked. Run it again where each handle it asked about has
579	    /// the same answer, and it asks the same questions in the same order and returns the same type. A handle that the
580	    /// conversion opened itself is settled inside it (it was found not to enclose the type at its own gate, which is
581	    /// recorded), so only the handles asked of the outer context are kept. A type in no cycle with its context asks
582	    /// nothing that encloses it and holds everywhere; one in a cycle holds where the same part of the cycle encloses
583	    /// it. Entries that hold in a context all agree, so which of them is found first, and so the order in which
584	    /// types were first reached, cannot show in the output.
585	    memo: Memo,
586	    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
