1	//! The heap budget of a whole-project run ([`crate::resolve`] and the calls beside it, which `extract` makes).
2	//!
3	//! A converted type is a tree the run builds in its own heap, and a type that expands to millions of members (a style
4	//! system declared in the project's own source, with hundreds of properties each over a hundred conditions) builds
5	//! tens of GiB of them, most of it copies of trees the converter recalls from its memo between two requests. The budget
6	//! is the safety net under every such shape: the run reads the heap before each component and every [`STEPS_PER_READ`]
7	//! steps (a checker request, or a type the converter converts or recalls), and once the heap is past the budget it
8	//! takes no further step: the conversion in flight stops at its next one. Every component it has not answered by then, the one in flight included, keeps its
9	//! structural result, and one warning says how many and why. Which components those are depends on how far each lane
10	//! had got, so past the budget the output depends on timing; a run that stays under it is unchanged.
11	//!
12	//! The heap is what mimalloc, the allocator of the CLI and of the native binding, has committed
13	//! (`mi_process_info`): the converter's trees, its memo and the merged props, all the Rust memory of the run. It
14	//! leaves out the checker's arenas, a range of their own that [`OnDemand`](crate::OnDemand)'s bound reads. A process
15	//! whose allocator is not mimalloc reads only mimalloc's own small commit, and so never reaches the budget.
16	
17	use std::sync::OnceLock;
18	use std::sync::atomic::{AtomicU64, Ordering};
19	
20	use caliper_docgen_core::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
21	
22	use crate::rpc::CallError;
23	
24	/// The most a budget derived from the machine allows: 8 GiB, about seven times the 1.1 GiB the largest corpus measured
25	/// commits (Mantine's core, shadcn, `gate-large`; docs/type-checker-integration.md).
26	pub const MAX_HEAP_BUDGET: u64 = 8 << 30;
27	
28	/// How many steps (checker requests, and types converted or recalled from the memo) a run takes between two reads of
29	/// the heap, besides the read before each component. A read costs about 0.9 µs (`mi_process_info`, measured over
30	/// 100,000 reads on an M-series Mac), so a read every 32 steps is about 30 ns a step.
31	const STEPS_PER_READ: u64 = 32;
32	
33	/// How large a whole-project run's heap may grow before it stops asking the checker (the module's documentation).
34	#[derive(Debug, Clone, Copy)]
35	pub struct HeapBudget {
36	    bytes: u64,
37	    meter: fn() -> u64,
38	}
39	
40	impl HeapBudget {
41	    /// The budget of this machine: 60% of the memory this process may use, at most [`MAX_HEAP_BUDGET`] (that, where
42	    /// the memory cannot be read). The memory is the physical memory, or on Linux the memory limit of the process's
43	    /// cgroup (a container's, a CI job's) when that is lower. 60%, because the heap is not all the process holds (the
44	    /// checker's arenas, the structural result, the JSON being written, and in the binding the host's own heap), and a
45	    /// run past that memory swaps or is killed rather than finishing.
46	    pub fn machine() -> Self {
47	        let usable = match (physical_memory(), cgroup_limit()) {
48	            (Some(physical), Some(limit)) => Some(physical.min(limit)),
49	            (physical, limit) => physical.or(limit),
50	        };
51	        Self::new(usable.map_or(MAX_HEAP_BUDGET, |bytes| (bytes / 10 * 6).min(MAX_HEAP_BUDGET)))
52	    }
53	
54	    /// A budget of `bytes` of mimalloc's committed heap.
55	    pub fn new(bytes: u64) -> Self {
56	        Self { bytes, meter: committed }
57	    }
58	
59	    /// A budget of `bytes` as `meter` reads the heap: tests stand in a meter whose readings they choose.
60	    #[cfg(test)]
61	    pub(crate) fn metered(bytes: u64, meter: fn() -> u64) -> Self {
62	        Self { bytes, meter }
63	    }
64	
65	    /// The bytes the budget allows.
66	    pub fn bytes(&self) -> u64 {
67	        self.bytes
68	    }
69	}
70	
71	/// The bytes mimalloc has committed for the whole process, as it counts them.
72	pub(crate) fn committed() -> u64 {
73	    let mut commit = 0usize;
74	    let null = std::ptr::null_mut();
75	    // SAFETY: `mi_process_info` writes each out-parameter that is not null and reads nothing else; `commit` outlives
76	    // the call.
77	    #[allow(unsafe_code)]
78	    unsafe {
79	        libmimalloc_sys::mi_process_info(null, null, null, null, null, &raw mut commit, null, null);
80	    }
81	    commit as u64
82	}
83	
84	/// The machine's physical memory in bytes.
85	#[cfg(unix)]
86	fn physical_memory() -> Option<u64> {
87	    // SAFETY: `sysconf` reads a system constant and has no other effect.
