/// SCRATCH: phase marker (mimalloc rss/peak/commit, tsrs arena resident MiB).
#[doc(hidden)]
#[allow(unsafe_code, clippy::print_stderr)]
pub fn phase(name: &str) {
    let (mut rss, mut peak, mut commit) = (0usize, 0usize, 0usize);
    let null = std::ptr::null_mut();
    unsafe { libmimalloc_sys::mi_process_info(null, null, null, &raw mut rss, &raw mut peak, &raw mut commit, null, null) };
    eprintln!("PHASE {name} rss={} peak={} commit={} arena={:?}", rss >> 20, peak >> 20, commit >> 20, checker::arena_mib());
}

/// SCRATCH: CAL_PROGRAMS overrides CHECKER_PROGRAMS.
fn programs_env() -> usize {
    std::env::var("CAL_PROGRAMS").ok().and_then(|v| v.parse().ok()).unwrap_or(CHECKER_PROGRAMS)
}

/// SCRATCH: CAL_BATCHES=N answers the request in N sequential batches of root files, each with its own checker.
fn batched(request: SemanticRequest, n: usize) -> SemanticOutcome {
    let order: Vec<Utf8PathBuf> = group_by_file(&request).2.iter().map(|f| f.to_path_buf()).collect();
    let per = order.len().div_ceil(n).max(1);
    let mut all = SemanticOutcome::default();
    for (i, chunk) in order.chunks(per).enumerate() {
